"""Half-open integer interval utilities."""


def _clean(intervals):
    return sorted((s, e) for s, e in intervals if s < e)


def merge(intervals):
    out = []
    for s, e in _clean(intervals):
        if out and s <= out[-1][1]:
            out[-1] = (out[-1][0], max(out[-1][1], e))
        else:
            out.append((s, e))
    return out


def free_gaps(intervals, window):
    ws, we = window
    if ws >= we:
        return []
    gaps = []
    cursor = ws
    for s, e in merge([(a, b) for a, b in _clean(intervals)]):
        if e <= cursor:
            continue
        if s > cursor:
            gaps.append((cursor, min(s, we)))
        cursor = max(cursor, e)
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    events = []
    for s, e in _clean(intervals):
        events.append((s, 1))
        events.append((e, -1))
    # start events before end events at same coordinate? No: half-open,
    # end at x frees before start at x counts, so sort ends first.
    events.sort(key=lambda t: (t[0], t[1]))
    depth = best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time_monotonic_default()):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self.clock = clock
        # key -> (value, expires_at or None) in LRU order (least recent first)
        self._entries = OrderedDict()

    def _is_expired(self, expires_at):
        return expires_at is not None and self.clock() >= expires_at

    def _purge_expired(self):
        for key in list(self._entries):
            if self._is_expired(self._entries[key][1]):
                del self._entries[key]

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be > 0")
        if key in self._entries:
            del self._entries[key]
        elif len(self._entries) >= self.capacity:
            self._purge_expired()
            if len(self._entries) >= self.capacity:
                self._entries.popitem(last=False)
        expires_at = self.clock() + ttl if ttl is not None else None
        self._entries[key] = (value, expires_at)

    def get(self, key, default=None):
        if key not in self._entries:
            return default
        value, expires_at = self._entries[key]
        if self._is_expired(expires_at):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        if key not in self._entries:
            return False
        value, expires_at = self._entries[key]
        if self._is_expired(expires_at):
            del self._entries[key]
            return False
        return True

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        before = len(self._entries)
        self._purge_expired()
        return before - len(self._entries)


